INSERT INTO blog_posts (id, author_id, title, content, subject, status, created_at, updated_at) VALUES
('b1000000-0000-4000-8000-000000000001', 'cd1f962b-3393-4c98-b6df-7b174384a295', 'Khởi động tiết học với bài toán thực tế', '<p>Trong tiết Toán 10 tuần này, mình thử mở đầu bằng câu hỏi về chi phí chuyến đi của lớp. Học sinh tự lập ẩn, so sánh phương án và trình bày cách giải.</p><p>Cách làm này giúp các em thấy phương trình bậc nhất gắn với tình huống quen thuộc hơn.</p>', 'MATH', 'PUBLISHED', now() - interval '8 days', now() - interval '8 days'),
('b1000000-0000-4000-8000-000000000002', 'cd1f962b-3393-4c98-b6df-7b174384a295', 'Mẹo giúp học sinh kiểm tra đáp án hình học', '<p>Thay vì chỉ đối chiếu kết quả cuối, mình yêu cầu học sinh kiểm tra ba điểm: giả thiết đã dùng, quan hệ song song/vuông góc và đơn vị đo.</p><ul><li>Đánh dấu dữ kiện trên hình.</li><li>Viết rõ định lý được áp dụng.</li><li>Ước lượng kết quả trước khi bấm máy tính.</li></ul>', 'MATH', 'PUBLISHED', now() - interval '6 days', now() - interval '6 days'),
('b1000000-0000-4000-8000-000000000003', 'cd1f962b-3393-4c98-b6df-7b174384a295', 'Hoạt động nhóm: khám phá hàm số bằng bảng giá trị', '<p>Mỗi nhóm nhận một bảng giá trị chưa hoàn chỉnh và dự đoán dạng đồ thị. Sau đó các em dùng GeoGebra hoặc giấy kẻ ô để kiểm chứng.</p><p>Phần chia sẻ cuối giờ rất hiệu quả vì học sinh tự phát hiện sai lệch trong dự đoán ban đầu.</p>', 'MATH', 'PUBLISHED', now() - interval '3 days', now() - interval '3 days'),
('b1000000-0000-4000-8000-000000000004', 'ac4369f4-0728-4594-bf81-2e7b77b7ab2b', 'Thí nghiệm nhỏ về tốc độ phản ứng an toàn trong lớp', '<p>Mình tổ chức thí nghiệm so sánh tốc độ phản ứng với viên sủi ở nước lạnh và nước ấm. Học sinh đo thời gian, lập bảng số liệu rồi giải thích biến số ảnh hưởng.</p><p>Lưu ý: chuẩn bị cốc nhựa, khăn lau và nhắc học sinh không nếm hóa chất.</p>', 'CHEMISTRY', 'PUBLISHED', now() - interval '7 days', now() - interval '7 days'),
('b1000000-0000-4000-8000-000000000005', '7fbd6b33-07a0-4999-8727-5f5be16c4ffe', 'Phiếu học tập ôn tập liên kết hóa học', '<p>Phiếu gồm ba phần: nhận diện loại liên kết, dự đoán tính chất chất và giải thích bằng cấu hình electron. Mình để phần tự đánh giá ở cuối để các em biết mục nào cần ôn thêm.</p>', 'CHEMISTRY', 'PUBLISHED', now() - interval '5 days', now() - interval '5 days'),
('b1000000-0000-4000-8000-000000000006', '99d76886-fed4-443d-af03-d6028e6b386a', 'Cách ghi nhớ dãy hoạt động hóa học bằng tình huống', '<p>Thay vì học thuộc lòng, lớp mình xây dựng một câu chuyện ngắn cho từng nhóm kim loại. Mỗi nhóm vẽ sơ đồ phản ứng minh họa và đổi bài cho nhóm khác kiểm tra.</p>', 'CHEMISTRY', 'PUBLISHED', now() - interval '2 days', now() - interval '2 days'),
('b1000000-0000-4000-8000-000000000007', '99e5cb8e-c92c-4a91-abac-7cd57bd45b08', 'Dạy định luật Newton qua tình huống xe đẩy', '<p>Một chiếc xe đẩy, vài quả cân và thước đo là đủ để học sinh quan sát mối liên hệ giữa lực, khối lượng và gia tốc.</p><p>Mình cho các nhóm dự đoán trước khi đo để phần thảo luận sau thí nghiệm sâu hơn.</p>', 'PHYSICS', 'PUBLISHED', now() - interval '9 days', now() - interval '9 days'),
('b1000000-0000-4000-8000-000000000008', '99e5cb8e-c92c-4a91-abac-7cd57bd45b08', 'Bản đồ khái niệm chương Sóng cơ', '<p>Cuối chương, học sinh cùng hoàn thiện bản đồ khái niệm gồm biên độ, chu kì, tần số, bước sóng và vận tốc truyền sóng.</p><p>Mỗi nhánh cần có công thức, đơn vị và một ví dụ đơn giản.</p>', 'PHYSICS', 'PUBLISHED', now() - interval '4 days', now() - interval '4 days'),
('b1000000-0000-4000-8000-000000000009', '99e5cb8e-c92c-4a91-abac-7cd57bd45b08', 'Câu hỏi dự đoán trước khi học về điện trường', '<p>Trước khi giới thiệu công thức, mình chiếu hình hai điện tích và yêu cầu học sinh vẽ hướng lực tác dụng lên điện tích thử tại vài vị trí.</p><p>Hoạt động chỉ mất năm phút nhưng giúp phát hiện sớm nhầm lẫn về chiều vectơ.</p>', 'PHYSICS', 'PUBLISHED', now() - interval '1 day', now() - interval '1 day')
