('c1000000-0000-4000-8000-000000000010', 'b1000000-0000-4000-8000-000000000007', 'cd1f962b-3393-4c98-b6df-7b174384a295', 'Mình cũng thường dùng xe đẩy, phần dự đoán làm lớp sôi nổi hơn.', now() - interval '8 days 18 hours', now() - interval '8 days 18 hours'),
('c1000000-0000-4000-8000-000000000011', 'b1000000-0000-4000-8000-000000000007', '7fbd6b33-07a0-4999-8727-5f5be16c4ffe', 'Bạn đo thời gian bằng điện thoại hay cổng quang điện?', now() - interval '8 days 15 hours', now() - interval '8 days 15 hours'),
